class Solution { public int[][] constructProductMatrix(int[][] grid) { int MOD = 12345; int n = grid.length, m = grid[0].length; int[][] res = new int[n][m]; long pre = 1; for (int i = 0; i < n; i++) { for (int j = 0; j < m; j++) { res[i][j] = (int) pre; pre = pre * (grid[i][j] % MOD) % MOD; } } long suf = 1; for (int i = n - 1; i >= 0; i--) { for (int j = m - 1; j >= 0; j--) { res[i][j] = (int) ((res[i][j] * suf) % MOD); suf = suf * (grid[i][j] % MOD) % MOD; } } return res; } }